insert into public.facilities (code, slug, name, summary, description, status, icon, pos_x, pos_y, sort) values
  ('A', 'main-temple', '{"en":"Main Radha-Krishna Temple","as":"মূল ৰাধা-কৃষ্ণ মন্দিৰ","hi":"मुख्य राधा-कृष्ण मंदिर"}'::jsonb, '{"en":"The spiritual and architectural centre of the campus.","as":"চৌহদৰ আধ্যাত্মিক আৰু স্থাপত্যৰ কেন্দ্ৰ।","hi":"परिसर का आध्यात्मिक और स्थापत्य केंद्र।"}'::jsonb, '{"en":"A white-marble temple with a rising shikhara, mandap and sanctum for the Radha-Krishna deities. Every other part of the campus is planned around it.","as":"ওখ শিখৰ, মণ্ডপ আৰু ৰাধা-কৃষ্ণ বিগ্ৰহৰ গৰ্ভগৃহসহ বগা মাৰ্বলৰ মন্দিৰ। চৌহদৰ আন সকলো অংশ ইয়াক কেন্দ্ৰ কৰি পৰিকল্পনা কৰা হৈছে।","hi":"ऊँचे शिखर, मंडप और राधा-कृष्ण विग्रहों के गर्भगृह वाला श्वेत संगमरमर का मंदिर। परिसर का हर दूसरा भाग इसी के चारों ओर नियोजित है।"}'::jsonb, 'proposed', 'temple', 50, 46, 1),
  ('B', 'gaushala', '{"en":"Gaushala","as":"গোশালা","hi":"गौशाला"}'::jsonb, '{"en":"A dedicated space for cow care, protection and gau seva.","as":"গৰুৰ যত্ন, সুৰক্ষা আৰু গো-সেৱাৰ বাবে নিৰ্দিষ্ট স্থান।","hi":"गायों की देखभाल, संरक्षण और गौ सेवा के लिए समर्पित स्थान।"}'::jsonb, '{"en":"Shelter, fodder and veterinary care for cows, with space for visitors to take part in gau seva.","as":"গৰুৰ বাবে আশ্ৰয়, খাদ্য আৰু পশু চিকিৎসা, লগতে অতিথিসকলে গো-সেৱাত অংশ ল''ব পৰা স্থান।","hi":"गायों के लिए आश्रय, चारा और पशु चिकित्सा, साथ ही आगंतुकों के लिए गौ सेवा में भाग लेने का स्थान।"}'::jsonb, 'proposed', 'cow', 18, 24, 2),
  ('C', 'amrit-sarovar', '{"en":"Amrit Sarovar","as":"অমৃত সৰোবৰ","hi":"अमृत सरोवर"}'::jsonb, '{"en":"A proposed water body for water conservation and aquatic biodiversity.","as":"পানী সংৰক্ষণ আৰু জলজ জৈৱ বৈচিত্ৰ্যৰ বাবে প্ৰস্তাৱিত জলাশয়।","hi":"जल संरक्षण और जलीय जैव विविधता के लिए प्रस्तावित जलाशय।"}'::jsonb, '{"en":"A pond to harvest rainwater and recharge groundwater, planted with lotus and native aquatic species.","as":"বৰষুণৰ পানী সংৰক্ষণ আৰু ভূগৰ্ভস্থ পানী পূৰণৰ বাবে পুখুৰী, য''ত পদুম আৰু থলুৱা জলজ উদ্ভিদ থাকিব।","hi":"वर्षा जल संचयन और भूजल पुनर्भरण के लिए तालाब, जिसमें कमल और देशी जलीय पौधे होंगे।"}'::jsonb, 'proposed', 'water', 27, 70, 3),
  ('D', 'bamboo-garden', '{"en":"Bamboo Garden","as":"বাঁহ বাগিচা","hi":"बाँस उद्यान"}'::jsonb, '{"en":"A bamboo landscape showcasing Assam''s natural heritage.","as":"অসমৰ প্ৰাকৃতিক ঐতিহ্য প্ৰদৰ্শন কৰা বাঁহনি।","hi":"असम की प्राकृतिक विरासत दर्शाता बाँस परिदृश्य।"}'::jsonb, '{"en":"Groves of bamboo species found in Assam, with shaded walks and pavilions in traditional bamboo craft.","as":"অসমত পোৱা বাঁহৰ প্ৰজাতিৰ বাঁহনি, ছাঁযুক্ত খোজকঢ়া পথ আৰু পৰম্পৰাগত বাঁহ শিল্পৰ চ''ৰা।","hi":"असम में पाई जाने वाली बाँस प्रजातियों के झुरमुट, छायादार पथ और पारंपरिक बाँस शिल्प के मंडप।"}'::jsonb, 'proposed', 'bamboo', 86, 50, 4),
  ('E', 'medicinal-garden', '{"en":"Medicinal Plant Garden","as":"ঔষধি উদ্ভিদ বাগিচা","hi":"औषधीय पौध उद्यान"}'::jsonb, '{"en":"A garden of medicinal and aromatic plants.","as":"ঔষধি আৰু সুগন্ধি উদ্ভিদৰ বাগিচা।","hi":"औषधीय और सुगंधित पौधों का उद्यान।"}'::jsonb, '{"en":"Labelled beds of medicinal and aromatic plants for learning, including tulsi for temple worship.","as":"শিকাৰ বাবে নামফলকযুক্ত ঔষধি আৰু সুগন্ধি উদ্ভিদৰ দাৰি, মন্দিৰৰ পূজাৰ বাবে তুলসীকে ধৰি।","hi":"सीखने के लिए नामपट्ट वाली औषधीय और सुगंधित पौधों की क्यारियाँ, मंदिर पूजा के लिए तुलसी सहित।"}'::jsonb, 'proposed', 'herb', 38, 20, 5),
  ('F', 'fruit-forest', '{"en":"Fruit Forest","as":"ফল অৰণ্য","hi":"फल वन"}'::jsonb, '{"en":"A green landscape of fruit-bearing trees.","as":"ফলৱতী গছৰ এক সেউজ পৰিৱেশ।","hi":"फलदार पेड़ों का हरा-भरा परिदृश्य।"}'::jsonb, '{"en":"A layered grove of fruit trees planted like a natural forest, offering shade and seasonal fruit.","as":"প্ৰাকৃতিক অৰণ্যৰ দৰে স্তৰে স্তৰে ৰোপণ কৰা ফলৰ গছৰ বাগিচা, যিয়ে ছাঁ আৰু ঋতুভিত্তিক ফল দিব।","hi":"प्राकृतिक वन की तरह परतों में लगाया गया फल वृक्षों का उपवन, जो छाया और मौसमी फल देगा।"}'::jsonb, 'proposed', 'fruit', 12, 54, 6),
  ('G', 'meditation-centre', '{"en":"Meditation Centre","as":"ধ্যান কেন্দ্ৰ","hi":"ध्यान केंद्र"}'::jsonb, '{"en":"A peaceful space for meditation, yoga and spiritual practice.","as":"ধ্যান, যোগ আৰু আধ্যাত্মিক সাধনাৰ বাবে শান্ত স্থান।","hi":"ध्यान, योग और आध्यात्मिक साधना के लिए शांत स्थान।"}'::jsonb, '{"en":"A quiet hall and open-air decks set apart from the busier areas, for meditation, yoga and retreats.","as":"ব্যস্ত অংশৰ পৰা আঁতৰত ধ্যান, যোগ আৰু সাধনা শিবিৰৰ বাবে এক শান্ত গৃহ আৰু মুকলি মঞ্চ।","hi":"व्यस्त क्षेत्रों से अलग, ध्यान, योग और साधना शिविरों के लिए एक शांत कक्ष और खुले मंच।"}'::jsonb, 'proposed', 'meditate', 74, 22, 7),
  ('H', 'cultural-space', '{"en":"Cultural and Religious Activity Space","as":"সাংস্কৃতিক আৰু ধৰ্মীয় কাৰ্যক্ষেত্ৰ","hi":"सांस्कृतिक और धार्मिक गतिविधि स्थल"}'::jsonb, '{"en":"For gatherings, Bhagavata path, discourses and celebrations.","as":"সমাৱেশ, ভাগৱত পাঠ, প্ৰৱচন আৰু উৎসৱৰ বাবে।","hi":"सभाओं, भागवत पाठ, प्रवचन और उत्सवों के लिए।"}'::jsonb, '{"en":"An open ground and covered hall for festivals such as Rasa Mahotsav, Bhagavata path and spiritual discourses.","as":"ৰাস মহোৎসৱ, ভাগৱত পাঠ আৰু আধ্যাত্মিক প্ৰৱচনৰ দৰে উৎসৱৰ বাবে মুকলি পথাৰ আৰু ঢাকনিযুক্ত সভাগৃহ।","hi":"रास महोत्सव, भागवत पाठ और आध्यात्मिक प्रवचन जैसे उत्सवों के लिए खुला मैदान और ढका हुआ सभागार।"}'::jsonb, 'proposed', 'gathering', 72, 74, 8)
insert into public.milestones (step, title, description) values
  (1, '{"en":"Project conceptualisation","as":"প্ৰকল্পৰ ধাৰণা গঠন","hi":"परियोजना की परिकल्पना"}'::jsonb, '{"en":"Defining the vision, purpose and scope of the temple campus.","as":"মন্দিৰ চৌহদৰ দৃষ্টিভংগী, উদ্দেশ্য আৰু পৰিসৰ নিৰ্ধাৰণ।","hi":"मंदिर परिसर की परिकल्पना, उद्देश्य और दायरे का निर्धारण।"}'::jsonb),
  (2, '{"en":"Land identification and planning","as":"মাটি চিনাক্তকৰণ আৰু পৰিকল্পনা","hi":"भूमि की पहचान और योजना"}'::jsonb, '{"en":"Identifying a suitable site and preparing an initial plan.","as":"উপযুক্ত স্থান চিনাক্ত কৰা আৰু প্ৰাৰম্ভিক পৰিকল্পনা প্ৰস্তুত কৰা।","hi":"उपयुक्त स्थल की पहचान और प्रारंभिक योजना तैयार करना।"}'::jsonb),
  (3, '{"en":"Architectural design","as":"স্থাপত্য ডিজাইন","hi":"स्थापत्य डिज़ाइन"}'::jsonb, '{"en":"Preparing temple and campus designs with architects.","as":"স্থপতিৰ সৈতে মন্দিৰ আৰু চৌহদৰ ডিজাইন প্ৰস্তুত কৰা।","hi":"वास्तुकारों के साथ मंदिर और परिसर के डिज़ाइन तैयार करना।"}'::jsonb),
  (4, '{"en":"Statutory permissions","as":"বৈধানিক অনুমতি","hi":"वैधानिक अनुमतियाँ"}'::jsonb, '{"en":"Applying for the approvals required by law before any construction.","as":"নিৰ্মাণৰ আগতে আইনগতভাৱে প্ৰয়োজনীয় অনুমোদনৰ বাবে আবেদন কৰা।","hi":"किसी भी निर्माण से पहले कानूनन आवश्यक अनुमतियों के लिए आवेदन।"}'::jsonb),
  (5, '{"en":"Campus development","as":"চৌহদ উন্নয়ন","hi":"परिसर विकास"}'::jsonb, '{"en":"Site preparation, access roads, water and power.","as":"স্থান প্ৰস্তুতি, প্ৰৱেশ পথ, পানী আৰু বিদ্যুৎ।","hi":"स्थल की तैयारी, पहुँच मार्ग, जल और बिजली।"}'::jsonb),
  (6, '{"en":"Temple construction","as":"মন্দিৰ নিৰ্মাণ","hi":"मंदिर निर्माण"}'::jsonb, '{"en":"Building the main Radha-Krishna temple.","as":"মূল ৰাধা-কৃষ্ণ মন্দিৰ নিৰ্মাণ।","hi":"मुख्य राधा-कृष्ण मंदिर का निर्माण।"}'::jsonb),
  (7, '{"en":"Landscaping and facilities","as":"প্ৰাকৃতিক সজ্জা আৰু সুবিধা","hi":"भू-दृश्य और सुविधाएँ"}'::jsonb, '{"en":"Gardens, gaushala, sarovar and other campus facilities.","as":"বাগিচা, গোশালা, সৰোবৰ আৰু চৌহদৰ আন সুবিধা।","hi":"उद्यान, गौशाला, सरोवर और परिसर की अन्य सुविधाएँ।"}'::jsonb),
  (8, '{"en":"Spiritual programmes begin","as":"আধ্যাত্মিক কাৰ্যসূচী আৰম্ভ","hi":"आध्यात्मिक कार्यक्रमों का आरंभ"}'::jsonb, '{"en":"Regular worship, festivals and programmes at the temple.","as":"মন্দিৰত নিয়মীয়া পূজা, উৎসৱ আৰু কাৰ্যসূচী।","hi":"मंदिर में नियमित पूजा, उत्सव और कार्यक्रम।"}'::jsonb)
